package dev.astralreach.core;
import java.util.*;
/** Privacy, depletion/reload semantics and physically connected generated sites. */
final class RescueExpeditionTests{
 static void run(){UUID owner=UUID.randomUUID(),friend=UUID.randomUUID(),stranger=UUID.randomUUID();long now=1_000_000;var b=new RescueBeacon(owner,"Pilot");CoreTests.check(!b.active(now)&&b.allows(owner)&&!b.allows(friend),"Fresh beacon has no free cell or audience");CoreTests.reject(()->b.load(stranger,now),"Other player cannot fuel someone's beacon");b.load(owner,now);CoreTests.check(b.active(now)&&b.remaining(now)==1_800_000,"Real cell enables exactly thirty minutes");CoreTests.reject(()->b.load(owner,now+1),"Partial cells cannot be overwritten or extended for free");b.invite(owner,friend,"Rescuer");CoreTests.check(b.allows(friend)&&!b.allows(stranger),"Invited rescuer only");b.toggle(owner,now+1000);CoreTests.check(!b.active(now+1000)&&b.remaining(now+1000)==1_799_000,"Stopping the signal does not stop its battery clock");var restored=new RescueBeacon(owner,"Pilot");restored.restore(b.expires(),b.enabled(),b.guests());CoreTests.check(!restored.active(now+2000)&&restored.remaining(now+2000)==1_798_000&&restored.allows(friend),"Reload preserves deadline and audience");restored.toggle(owner,now+2000);restored.revoke(owner,friend);CoreTests.check(!restored.allows(friend)&&restored.active(now+2000),"Revocation immediately removes access");CoreTests.check(!restored.active(now+RescueBeacon.CELL_MILLIS)&&restored.remaining(now+RescueBeacon.CELL_MILLIS)==0,"Unloaded/offline expiry cannot reset charge");CoreTests.reject(()->restored.toggle(owner,now+RescueBeacon.CELL_MILLIS),"Empty battery cannot restart");for(int i=0;i<8;i++)restored.invite(owner,UUID.randomUUID(),"Crew"+i);CoreTests.reject(()->restored.invite(owner,UUID.randomUUID(),"Overflow"),"Finite invitation count");
  for(int seed:new int[]{91023,0,7,12987,-99}){
   var site=new LunarExpedition.Site(seed,0,145);var relay=site.relay();CoreTests.check(!LunarTubes.protectedSite(relay.x(),relay.z()),"First relay avoids landing protections");CoreTests.check("AR_DamagedRelay".equals(LunarExpedition.block(site,relay.x(),relay.y()+1,relay.z())),"Physical relay in first playable site");CoreTests.check(LunarExpedition.affectedColumn(site,relay.x(),relay.z()),"Sparse generation preserves relay column");
   for(int z=site.start();z<=site.start()+512;z++){
    int x=site.axis(z);var tube=LunarTubes.column(seed,x,z,LunarSurface.height(seed,x,z));CoreTests.check(tube.present()&&tube.ceiling()-tube.floor()>=4,"Two skylights retain one connected walkable lava tube");
    if(z>site.start()){int px=site.axis(z-1);var previous=LunarTubes.column(seed,px,z-1,LunarSurface.height(seed,px,z-1));CoreTests.check(Math.abs(tube.floor()-previous.floor())<=1,"Longitudinal cave path never requires impossible climbing");}
   }
   for(int i=0;i<2;i++){var a=site.archive(i);CoreTests.check("AR_ResearchArchive".equals(LunarExpedition.block(site,a.x(),a.y(),a.z())),"Both archives physically generated");CoreTests.check(LunarExpedition.affectedColumn(site,a.x(),a.z()),"Sparse generation preserves both terminal columns");CoreTests.check(LunarExpedition.reward(i).values().stream().allMatch(v->v>0),"Finite meaningful archive rewards");}
   var h=site.shelter();for(int dz:new int[]{-9,9})for(int y=1;y<=4;y++)CoreTests.check("Empty".equals(LunarExpedition.block(site,h.x(),h.y()+y,h.z()+dz)),"Both shelter doors remain open with four-block clearance");
   CoreTests.check(LunarExpedition.nearby(seed,relay.x(),relay.z()).id().equals(site.id()),"Chunk-independent same site coordinates");CoreTests.check(LunarExpedition.block(site,16,64,16)==null,"Never overwrite protected landing zone");
  }
 }
}
